def f(q, queries):
    answer = []
    a = {}
    b = []
    for query in queries:
        if query[0] == 0:
            if query[1] in a:
                b.append(query[1])
            else:
                a[query[1]] = 1
        elif query[0] == 1:
            if query[1] in a:
                del a[query[1]]
            elif query[1] in b:
                b.remove(query[1])
            else:
                print("No such element")
        elif query[0] == 2:
            if query[1] in a:
                a[query[1]] = 0
            else:
                print("No such element")
        else:
            count = 0
            for i in range(query[1], query[2] + 1):
                if i in a:
                    count += a[i]
            answer.append(count)
    return answer
```

